-- Defaults from checked-in kv/*.json; existing operator definitions are preserved.
INSERT OR IGNORE INTO app_definition_documents(definition_key,value_json) VALUES ('backend-config:v1','{"version":1,"market_stale_days":3,"rate_limit_window_seconds":60,"rate_limit_register":10,"rate_limit_authenticated":120,"rate_limit_public":300}');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (95,100,'S+','極めて健全','分散、増配力、利回り、集中度のバランスが極めて良好です。現在の構成を基本線とし、買い増しでは上位銘柄と同一業種への集中だけを抑えると安定性を維持しやすい状態です。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (90,94,'S','非常に健全','全体の質は非常に高く、配当の持続性と分散の両面で大きな弱点は見当たりにくい状態です。買い増し時は利回りだけでなく、増配余地と業種比率も確認してください。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (85,89,'A+','かなり健全','主力銘柄の配当継続性と分散は良好です。一部の比率を整える余地はありますが、大きな組み替えを急ぐ必要性は低い状態です。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (80,84,'A','健全','配当水準と増配力は良好です。特定銘柄または特定業種への比率が高い場合は、新規資金を別業種へ振り向けると全体の安定性が高まります。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (75,79,'B+','良好','全体としては良好ですが、一部に集中や減配耐性の弱さがあります。高比率銘柄の配当性向と利益推移を優先して確認してください。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (70,74,'B','概ね良好','配当水準は確保できていますが、分散、増配実績、収益安定性のいずれかに改善余地があります。買い増し先を選ぶ際は弱い項目を補う方向が適しています。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (65,69,'C+','注意点あり','一定の配当収入は期待できますが、集中度または業績変動の影響を受けやすい構成です。上位銘柄の比率と配当余力を確認してください。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (60,64,'C','要点検','利回りは確保できていても、減配耐性や分散に弱さがあります。高利回りだけを理由に保有比率を上げず、利益と配当性向の推移を確認してください。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (50,59,'D','見直し推奨','高利回り銘柄への偏り、業種集中、減配余地のいずれかが目立つ状態です。新規買い増しより先に、リスクの大きい保有銘柄を特定することが有効です。');
INSERT OR IGNORE INTO diagnosis_bands(min_score,max_score,grade,title,comment) VALUES (0,49,'E','要再構成','配当の持続性または分散に大きな弱点があります。利回りの高さよりも、利益の安定性、配当性向、上位銘柄比率を優先して構成を見直す必要があります。');
INSERT OR IGNORE INTO app_definition_documents(definition_key,value_json) VALUES ('portfolio-analysis-definitions:v1','{"version":1,"healthy_payout_ratio_max":70.0,"scores":{"concentration":[{"max":15.0,"score":100},{"max":25.0,"score":85},{"max":35.0,"score":65},{"max":50.0,"score":45},{"score":20}],"sector_count":[{"min":8,"score":100},{"min":6,"score":85},{"min":4,"score":70},{"min":3,"score":55},{"min":2,"score":40},{"min":0,"score":20}],"holding_count":[{"min":15,"score":100},{"min":10,"score":85},{"min":7,"score":70},{"min":5,"score":55},{"min":3,"score":40},{"min":0,"score":20}],"dividend_growth_years":[{"min":10.0,"score":100},{"min":5.0,"score":85},{"min":3.0,"score":70},{"min":1.0,"score":55},{"min":0.0,"score":40}],"healthy_share":[{"min":80.0,"score":100},{"min":65.0,"score":85},{"min":50.0,"score":70},{"min":35.0,"score":50},{"min":0.0,"score":30}]},"missing_scores":{"concentration":40,"dividend_growth_years":50,"healthy_share":50},"weights":{"concentration":25,"sector":20,"holdings":10,"dividend_growth":15,"payout":15,"fcf":15},"stability_weights":{"sector":35,"concentration":35,"fcf":30},"dividend_risk_weights":{"payout":40,"fcf":35,"dividend_growth":25},"stability_labels":[{"min":85,"label":"非常に高い"},{"min":70,"label":"高い"},{"min":55,"label":"標準"},{"min":40,"label":"低め"},{"min":0,"label":"低い"}],"dividend_risk_labels":[{"max":15,"label":"低い"},{"max":30,"label":"やや低い"},{"max":45,"label":"標準"},{"max":60,"label":"やや高い"},{"max":100,"label":"高い"}]}');
INSERT OR IGNORE INTO app_definition_documents(definition_key,value_json) VALUES ('stock-analysis-definitions:v1','{"metric_rules":[{"bands":[{"label":"割安","score":100,"max":10,"comment":"利益に対して株価がかなり低い水準です。ただし、一時的な利益増加や将来の業績悪化懸念によってPERが低くなっていないか確認してください。"},{"label":"やや割安","score":80,"max":15,"comment":"利益に対して株価は比較的低めです。同業他社や自社の過去水準と比べ、利益の持続性も合わせて確認すると判断しやすくなります。"},{"label":"適正","score":65,"max":20,"comment":"利益水準に対しておおむね中立的な評価です。PERだけで判断せず、利益成長率や配当余力と合わせて確認してください。"},{"label":"やや割高","score":45,"max":30,"comment":"利益に対して株価評価がやや高めです。今後の利益成長が現在の評価倍率に見合うか確認が必要です。"},{"label":"割高","score":25,"max":99999,"comment":"利益に対して株価評価が高い状態です。成長期待が崩れた場合の価格調整リスクも考慮してください。"}],"label":"PER","key":"per","weight":15},{"bands":[{"label":"資産面で割安","score":100,"max":0.8,"comment":"純資産に対して株価が低く、資産面では割安感があります。資産の質や収益力が低いために評価されていない可能性も確認してください。"},{"label":"割安","score":85,"max":1.2,"comment":"純資産に対して比較的低い評価です。ROEや利益率が安定している場合は、割安性の裏付けになりやすい状態です。"},{"label":"適正","score":65,"max":2.0,"comment":"純資産に対しておおむね標準的な評価です。資本効率や収益成長と合わせて妥当性を確認してください。"},{"label":"高め","score":45,"max":3.5,"comment":"純資産に対して評価が高めです。高いROEや成長性が継続できるかが重要になります。"},{"label":"高評価","score":25,"max":99999,"comment":"純資産に対して高い評価が付いています。収益性が低下した場合は評価倍率が縮小しやすいため注意が必要です。"}],"label":"PBR","key":"pbr","weight":10},{"bands":[{"label":"余力大","score":85,"max":30,"comment":"利益に対する配当負担は低く、増配や業績悪化への耐性に余裕があります。一方で、株主還元方針が弱くないかも確認してください。"},{"label":"健全","score":100,"max":50,"comment":"利益と配当のバランスが良く、継続配当の余力を確保しやすい水準です。"},{"label":"やや高め","score":70,"max":70,"comment":"配当負担はやや高めですが、現時点では一定の余力があります。利益の安定性と今後の増配方針を確認してください。"},{"label":"高め","score":45,"max":90,"comment":"利益の多くを配当に回しており、利益減少時には配当維持余力が小さくなります。"},{"label":"要警戒","score":20,"max":99999,"comment":"利益に対する配当負担が非常に高い状態です。減益や一時利益の反動で減配につながらないか重点確認が必要です。"}],"label":"配当性向","key":"payout_ratio","weight":20},{"bands":[{"score":100,"min":60,"label":"非常に高い","comment":"自己資本の厚みが非常に大きく、財務面の耐久力は高い状態です。ただし、業種によって適正水準は異なります。"},{"score":85,"min":40,"label":"高い","comment":"自己資本が十分に確保され、財務安定性は高めです。有利子負債や資金繰りも合わせて確認するとより確実です。"},{"score":65,"min":25,"label":"標準","comment":"自己資本比率は標準的です。事業の安定性や負債構成と合わせて評価してください。"},{"score":45,"min":15,"label":"低め","comment":"自己資本の厚みがやや弱く、景気悪化や金利上昇時の負担増に注意が必要です。"},{"score":25,"min":-99999,"label":"低い","comment":"自己資本比率が低く、財務余力に注意が必要です。借入依存度、利払い負担、資金繰りを確認してください。"}],"label":"自己資本比率","key":"equity_ratio","weight":15},{"bands":[{"score":100,"min":15,"label":"高収益","comment":"売上に対する営業利益の割合が高く、本業の収益力は強い状態です。利益率の持続性と競争優位性も確認してください。"},{"score":85,"min":10,"label":"良好","comment":"営業利益率は良好で、本業の収益力は強めです。過去数年の推移が安定しているか確認してください。"},{"score":65,"min":5,"label":"標準","comment":"営業利益率は標準的です。業界平均と比較し、改善傾向か悪化傾向かを見ることが重要です。"},{"score":45,"min":2,"label":"低め","comment":"営業利益率が低めで、コスト上昇や売上減少の影響を受けやすい状態です。"},{"score":20,"min":-99999,"label":"低収益","comment":"本業の収益力が弱い状態です。構造的な低採算なのか、一時要因なのかを確認してください。"}],"label":"営業利益率","key":"operating_margin","weight":15},{"bands":[{"score":100,"min":10,"label":"非常に強い","comment":"売上に対して十分なフリーキャッシュフローを生み出しており、配当、投資、債務返済に使える現金余力が非常に強い状態です。"},{"score":85,"min":5,"label":"強い","comment":"フリーキャッシュフローは良好で、株主還元や成長投資を支えやすい状態です。継続性も確認してください。"},{"score":65,"min":0,"label":"確保","comment":"フリーキャッシュフローは黒字を確保しています。設備投資負担や運転資金の変動で悪化しないか推移を確認してください。"},{"score":40,"min":-5,"label":"弱い","comment":"フリーキャッシュフローが弱く、投資負担や営業キャッシュの減少が影響している可能性があります。"},{"score":20,"min":-99999,"label":"赤字","comment":"フリーキャッシュフローが赤字です。配当原資を借入や手元資金に依存していないか確認が必要です。"}],"label":"FCF余力","key":"fcf_margin","weight":15},{"bands":[{"score":100,"min":10,"label":"長期増配","comment":"10年以上の連続増配実績があり、株主還元の継続性は非常に高い実績です。今後も利益とキャッシュが増配を支えられるか確認してください。"},{"score":85,"min":5,"label":"増配継続","comment":"5年以上の連続増配実績があり、還元方針の安定性が見られます。"},{"score":70,"min":3,"label":"実績あり","comment":"複数年の増配実績があります。増配率と利益成長が釣り合っているか確認してください。"},{"score":55,"min":1,"label":"短期実績","comment":"増配実績はまだ短く、長期的な継続性の判断には追加実績が必要です。"},{"score":40,"min":-99999,"label":"実績限定","comment":"連続増配の実績は限定的です。配当方針や過去の減配履歴も合わせて確認してください。"}],"label":"連続増配","key":"dividend_growth_years","weight":10}],"narrative_settings":{"strength_threshold":80,"weakness_threshold":59,"boundary_ratio":0.18,"band_position_lower_ratio":0.3333333333,"band_position_upper_ratio":0.6666666667,"max_strengths":2,"max_weaknesses":2},"overall_bands":[{"title":"非常に良好","min_score":90,"grade":"S","comment":"割安性、財務、配当、収益、キャッシュ、増配実績を総合すると非常に良好です。","detail":"主要7指標の多くが高水準で、財務・収益・配当のバランスが良好です。ただし、総合点が高くても現在株価が割高な場合や、一時的な利益で指標が改善している場合は別途確認が必要です。","max_score":100},{"title":"良好","min_score":80,"grade":"A","comment":"総合的に良好です。弱い指標を確認しながら価格水準を見て判断できます。","detail":"全体として良好ですが、一部に弱い指標が残っています。最も点数の低い項目とその過去推移を確認し、価格面の余裕も合わせて判断してください。","max_score":89},{"title":"概ね良好","min_score":70,"grade":"B","comment":"大きな弱点は限定的ですが、財務または配当の一部に確認余地があります。","detail":"大きな問題は限定的ですが、複数指標の組み合わせによっては将来の配当余力や財務安定性に差が出ます。弱い項目を重点的に確認してください。","max_score":79},{"title":"注意点あり","min_score":60,"grade":"C","comment":"複数の指標に注意点があります。買い増し前に弱い項目の推移を確認してください。","detail":"注意が必要な指標が複数あります。特に配当性向、FCF、自己資本比率の弱さが重なる場合は、配当維持余力を慎重に確認してください。","max_score":69},{"title":"要点検","min_score":0,"grade":"D","comment":"財務、配当、収益または価格のいずれかに明確な弱さがあります。","detail":"明確に弱い指標が含まれています。総合点だけで判断せず、低評価となった項目の原因と改善可能性を確認してください。","max_score":59}],"version":1}');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (1,8.0,0.7,'超割安・資産価値圏','強い買場候補','PER、PBRとも極めて低い水準です。業績悪化や一時要因による低評価でないかを確認できれば、割安度は非常に高い状態です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (2,8.0,1.0,'超割安・資産価値圏','強い買場候補','PER、PBRとも極めて低い水準です。業績悪化や一時要因による低評価でないかを確認できれば、割安度は非常に高い状態です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (3,8.0,1.3,'ディープバリュー圏','積極検討','利益倍率と純資産倍率の両面で割安です。配当余力と財務に問題がなければ、中長期の買い増し候補になりやすい水準です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (4,8.0,1.6,'王道バリュー圏','買い増し検討','市場平均より低い評価に収まりやすい水準です。利益の安定性と配当政策を確認しながら買い増しを検討できます。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (5,8.0,2.0,'割安寄り適正圏','段階的に検討','割高感は小さく、業績と成長率が安定していれば妥当性のある水準です。一括ではなく段階的な買い増しと相性があります。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (6,8.0,2.5,'適正評価圏','選別して検討','極端な割安感はありません。利益成長、配当成長、ROEなどの質が伴っているかを確認して判断する水準です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (7,8.0,3.5,'やや高評価圏','押し目待ちも検討','一定の成長期待が価格に織り込まれています。業績が想定通り伸びるかを確認し、買い急がない判断も有効です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (8,8.0,5.0,'高評価圏','慎重検討','成長期待を前提とした評価です。利益成長率が鈍化すると倍率調整を受けやすいため、決算内容の確認が重要です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (9,8.0,8.0,'割高警戒圏','価格待ち','現在の評価には高い成長期待が含まれています。新規買いでは、成長率と利益率が評価倍率に見合うか慎重に確認してください。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (10,8.0,99999.0,'過熱警戒圏','原則様子見','PERが高く、期待先行になりやすい水準です。好材料が既に価格へ反映されている可能性があるため、押し目を待つ余地があります。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (11,10.0,0.7,'ディープバリュー圏','積極検討','利益倍率と純資産倍率の両面で割安です。配当余力と財務に問題がなければ、中長期の買い増し候補になりやすい水準です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (12,10.0,1.0,'ディープバリュー圏','積極検討','利益倍率と純資産倍率の両面で割安です。配当余力と財務に問題がなければ、中長期の買い増し候補になりやすい水準です。');
