INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (14,10.0,1.6,'王道バリュー圏','買い増し検討','市場平均より低い評価に収まりやすい水準です。利益の安定性と配当政策を確認しながら買い増しを検討できます。');
