INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (16,10.0,2.5,'適正評価圏','選別して検討','極端な割安感はありません。利益成長、配当成長、ROEなどの質が伴っているかを確認して判断する水準です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (17,10.0,3.5,'やや高評価圏','押し目待ちも検討','一定の成長期待が価格に織り込まれています。業績が想定通り伸びるかを確認し、買い急がない判断も有効です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (18,10.0,5.0,'高評価圏','慎重検討','成長期待を前提とした評価です。利益成長率が鈍化すると倍率調整を受けやすいため、決算内容の確認が重要です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (19,10.0,8.0,'割高警戒圏','価格待ち','現在の評価には高い成長期待が含まれています。新規買いでは、成長率と利益率が評価倍率に見合うか慎重に確認してください。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (20,10.0,99999.0,'過熱警戒圏','原則様子見','PERが高く、期待先行になりやすい水準です。好材料が既に価格へ反映されている可能性があるため、押し目を待つ余地があります。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (21,12.0,0.7,'王道バリュー圏','買い増し検討','市場平均より低い評価に収まりやすい水準です。利益の安定性と配当政策を確認しながら買い増しを検討できます。');
