INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (25,12.0,2.0,'割安寄り適正圏','段階的に検討','割高感は小さく、業績と成長率が安定していれば妥当性のある水準です。一括ではなく段階的な買い増しと相性があります。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (26,12.0,2.5,'適正評価圏','選別して検討','極端な割安感はありません。利益成長、配当成長、ROEなどの質が伴っているかを確認して判断する水準です。');
INSERT OR IGNORE INTO valuation_scenarios(id,per_max,pbr_max,title,badge,comment) VALUES (27,12.0,3.5,'やや高評価圏','押し目待ちも検討','一定の成長期待が価格に織り込まれています。業績が想定通り伸びるかを確認し、買い急がない判断も有効です。');
