INSERT OR IGNORE INTO app_definition_documents(definition_key,value_json) VALUES ('watchlist-analysis-definitions:v1','{"display_fields":["buy_zone","overall_grade","valuation_label","risk_flag"],"buy_zone":[{"comment":"現在利回りが設定目標に到達しています。","detail":"設定した目標利回りを満たしているため、価格面では買場条件に入っています。最終判断では、総合グレードや配当余力、直近決算も合わせて確認してください。","label":"目標到達","status":"TARGET","min_ratio":1.0},{"comment":"目標利回りまで5%以内です。","detail":"目標水準が近く、株価の小幅な下落や増配で条件到達する可能性があります。買場通知の対象として優先的に監視する水準です。","label":"買場接近","status":"NEAR","min_ratio":0.95},{"comment":"目標水準へ近づいています。","detail":"まだ目標利回りには届いていませんが、通常時より買場に近い水準です。今後の株価変動や配当予想の更新を継続して確認してください。","label":"監視圏","status":"WATCH","min_ratio":0.85},{"comment":"設定した目標利回りにはまだ距離があります。","detail":"現在価格では設定した利回り条件を十分に満たしていません。無理に追わず、株価調整または増配によって条件が改善するのを待つ状態です。","label":"価格待ち","status":"WAIT","min_ratio":0.0}],"version":1}');
